exercise.solution:
data class Coupon(val code: String, val discount: Int, val expired: Boolean)

// 네 가지 실패(짧음·조회 실패·만료·할인율 0)를 전부 null 로 모아 마지막 ?: 하나로 받는다.
// 긍정 조건은 takeIf, 부정 조건(만료가 아니면)은 takeUnless 로 써야 ! 없이 읽힌다.
fun describeCoupon(raw: String?, coupons: Map<String, Coupon>): String =
    raw?.trim()?.uppercase()
        ?.takeIf { it.length >= 4 }
        ?.let { coupons[it] }
        ?.takeUnless { it.expired }
        ?.takeIf { it.discount > 0 }
        ?.let { "${it.code} 적용 — ${it.discount}% 할인" }
        ?: "쿠폰 적용 안 됨 (입력: ${raw ?: "없음"})"

// ?: return 으로 가드 절을 한 표현식에 담는다. 아래부터 coupon 은 non-null 타입.
fun finalPrice(price: Int, raw: String?, coupons: Map<String, Coupon>): Int {
    val coupon = raw?.trim()?.uppercase()
        ?.let { coupons[it] }
        ?.takeUnless { it.expired }
        ?: return price
    return price - price * coupon.discount / 100
}

fun main() {
    val coupons = mapOf(
        "WELCOME" to Coupon("WELCOME", 10, expired = false),
        "VIP30" to Coupon("VIP30", 30, expired = false),
        "OLD2024" to Coupon("OLD2024", 50, expired = true),
        "ZERO" to Coupon("ZERO", 0, expired = false),
    )

    val inputs = listOf("  welcome ", "vip30", "old2024", "zero", "nope", "ab", "   ", null)
    for (raw in inputs) println(describeCoupon(raw, coupons))

    println(finalPrice(20000, " welcome ", coupons))
    println(finalPrice(20000, "vip30", coupons))
    println(finalPrice(20000, "old2024", coupons))
    println(finalPrice(20000, null, coupons))
}
